def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Next character must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        # Skip the comma if present
                        if i < len(line) and line[i] == ',':
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field - runs to next comma
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

